2	 * `int(str)` with CPython's exact grammar, returning a BigInt so that
3	 * arbitrary-precision arithmetic keeps working.
4	 */
5	
6	import { PyValueError } from './errors.mjs';
7	import { reprString, truncateRepr } from './repr.mjs';
8	import { decimalValue, isPySpace } from './unicodedata.mjs';
9	
10	/** CPython formats this message with `%.200R`, i.e. a 200 character cap. */
11	const MESSAGE_REPR_LIMIT = 200;
12	
13	function invalidLiteral(text) {
14	  const shown = truncateRepr(reprString(text), MESSAGE_REPR_LIMIT);
15	  return new PyValueError(`invalid literal for int() with base 10: ${shown}`);
16	}
17	
18	function stripPySpace(characters) {
19	  let start = 0;
20	  let end = characters.length;
21	  while (start < end && isPySpace(characters[start].codePointAt(0))) start += 1;
22	  while (end > start && isPySpace(characters[end - 1].codePointAt(0))) end -= 1;
23	  return characters.slice(start, end);
24	}
25	
26	/**
27	 * Grammar accepted by `int(x, 10)`:
28	 *   whitespace* [+-]? digit (['_']? digit)* whitespace*
29	 * where `digit` is any Unicode decimal digit and `_` may only separate digits.
30	 *
31	 * @param {string} text
32	 * @returns {bigint}
33	 */
34	export function pyInt(text) {
35	  const characters = stripPySpace(Array.from(text));
36	  let index = 0;
37	  let negative = false;
38	
39	  if (index < characters.length && (characters[index] === '+' || characters[index] === '-')) {
40	    negative = characters[index] === '-';
41	    index += 1;
42	  }
43	
44	  let digits = '';
45	  let previousWasDigit = false;
46	  for (; index < characters.length; index += 1) {
47	    const character = characters[index];
48	    if (character === '_') {
49	      // An underscore must sit between two digits.
50	      if (!previousWasDigit) throw invalidLiteral(text);
51	      previousWasDigit = false;
52	      continue;
53	    }
54	    const value = decimalValue(character.codePointAt(0));
55	    if (value < 0) throw invalidLiteral(text);
56	    digits += String(value);
57	    previousWasDigit = true;
58	  }
59	
60	  if (digits === '' || !previousWasDigit) throw invalidLiteral(text);
61	  const magnitude = BigInt(digits);
62	  return negative ? -magnitude : magnitude;
63	}
