10	/**
11	 * One traceback frame.
12	 *
13	 * `colno`/`endColno` are the zero based byte offsets of the failing expression
14	 * within its source line, as the code object records them; they drive the caret
15	 * line.  Frames without that information (a library compiled elsewhere) pass
16	 * null and never get carets.
17	 */
18	export function frame({ file, line, func, colno = null, endColno = null }) {
19	  return { file, line, func, colno, endColno };
20	}
21	
22	/** Base class for every emulated Python exception. */
23	export class PyException extends Error {
24	  /**
25	   * @param {string} type    exception class name, e.g. "ValueError"
26	   * @param {string} message the `str(exc)` text
27	   */
28	  constructor(type, message) {
29	    super(message === '' ? type : `${type}: ${message}`);
30	    this.pyType = type;
31	    this.pyMessage = message;
32	    /** Frames between the module level and the raise site, outermost first. */
33	    this.pyTraceback = [];
34	  }
35	
36	  /** The closing `Type: message` line of a traceback. */
37	  get exceptionLine() {
38	    return this.pyMessage === '' ? this.pyType : `${this.pyType}: ${this.pyMessage}`;
39	  }
40	}
41	
42	export class PyValueError extends PyException {
43	  constructor(message) {
44	    super('ValueError', message);
45	  }
46	}
47	
48	export class PyTypeError extends PyException {
49	  constructor(message) {
50	    super('TypeError', message);
51	  }
52	}
53	
54	export class PyMemoryError extends PyException {
55	  constructor(message = '') {
56	    super('MemoryError', message);
57	  }
58	}
