60	/**
61	 * `SystemExit`, raised by `argparse` via `parser.exit()` / `parser.error()`.
62	 * It is never reported as an unhandled exception; it only sets the status.
63	 */
64	export class SystemExit extends Error {
65	  constructor(code = 0) {
66	    super(`SystemExit: ${code}`);
67	    this.code = code;
68	  }
69	}
