71	/**
72	 * Record `frame` as the caller of whatever is already on the traceback, the way
73	 * the interpreter grows a traceback while an exception propagates outwards.
74	 */
75	export function withFrame(error, frameToAdd) {
76	  if (error instanceof PyException) error.pyTraceback.unshift(frameToAdd);
77	  return error;
78	}
79	
80	/** Run `operation`, tagging any Python-level error with `frameToAdd`. */
81	export function inFrame(frameToAdd, operation) {
82	  try {
83	    return operation();
84	  } catch (error) {
85	    throw withFrame(error, frameToAdd);
86	  }
87	}
